    const d = it.data || {};
    const rep = d.rep || "（担当者未設定）";
    if (!map[rep]) map[rep] = { rep: rep, visits: 0, prospect: 0 };
    map[rep].visits += Number(d.visits) || 0;
    map[rep].prospect += Number(d.prospect) || 0;
  }
  const reps = Object.values(map).map(r => ({ week_start: i.start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const lines = reps.map(r => r.rep + ": 訪問 " + r.visits + " 件・見込み額 " + r.prospect + " 円").join("\n");
  return { count: reps.length, reps: reps, lines: lines };
}

