function main(i) {
  const today = i.date;
  const rows = (i.items || []).map((r) => r.data).filter((d) => d.due_on && d.due_on < today && !d.returned_on);
  rows.sort((a, b) => (a.due_on < b.due_on ? -1 : a.due_on > b.due_on ? 1 : 0));
  const esc = (s) => String(s ?? '').replace(/\|/g, '\\|');
  const lines = ['# 延滞一覧 ' + today, '', '対象: ' + rows.length + ' 件', ''];
  if (rows.length === 0) {
    lines.push('延滞はありません。');
  } else {
    lines.push('| 管理番号 | 借りた人 | 返却予定日 |', '| --- | --- | --- |');
    for (const d of rows) lines.push('| ' + esc(d.code) + ' | ' + esc(d.borrower) + ' | ' + esc(d.due_on) + ' |');
  }
  return { text: lines.join('\n') + '\n' };
}

